CREATE TABLE "user" ("id" text PRIMARY KEY NOT NULL,"name" text NOT NULL,"email" text NOT NULL UNIQUE,"emailVerified" boolean NOT NULL DEFAULT false,"image" text,"createdAt" timestamp NOT NULL DEFAULT now(),"updatedAt" timestamp NOT NULL DEFAULT now(),"role" text NOT NULL DEFAULT 'agent',"active" boolean NOT NULL DEFAULT true);
CREATE TABLE "session" ("id" text PRIMARY KEY NOT NULL,"expiresAt" timestamp NOT NULL,"token" text NOT NULL UNIQUE,"createdAt" timestamp NOT NULL DEFAULT now(),"updatedAt" timestamp NOT NULL DEFAULT now(),"ipAddress" text,"userAgent" text,"userId" text NOT NULL,FOREIGN KEY ("userId") REFERENCES "user" ("id") ON DELETE cascade);
CREATE TABLE "account" ("id" text PRIMARY KEY NOT NULL,"accountId" text NOT NULL,"providerId" text NOT NULL,"userId" text NOT NULL,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamp,"refreshTokenExpiresAt" timestamp,"scope" text,"password" text,"createdAt" timestamp NOT NULL DEFAULT now(),"updatedAt" timestamp NOT NULL DEFAULT now(),FOREIGN KEY ("userId") REFERENCES "user" ("id") ON DELETE cascade);
CREATE TABLE "verification" ("id" text PRIMARY KEY NOT NULL,"identifier" text NOT NULL,"value" text NOT NULL,"expiresAt" timestamp NOT NULL,"createdAt" timestamp DEFAULT now(),"updatedAt" timestamp DEFAULT now());
CREATE TABLE "agency_settings" ("id" integer PRIMARY KEY NOT NULL DEFAULT 1,"name" text NOT NULL,"address" text,"phone" text,"email" text,"website" text,"tax_id" text,"default_currency" text NOT NULL DEFAULT 'USD',"dossier_prefix" text NOT NULL DEFAULT 'DOS',"quote_prefix" text NOT NULL DEFAULT 'DEV',"invoice_prefix" text NOT NULL DEFAULT 'FAC',"receipt_prefix" text NOT NULL DEFAULT 'REC',"client_prefix" text NOT NULL DEFAULT 'CLI',"document_footer" text,"updated_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "counters" ("key" text PRIMARY KEY NOT NULL,"value" integer NOT NULL DEFAULT 0);
CREATE TABLE "currencies" ("code" text PRIMARY KEY NOT NULL,"name" text NOT NULL,"symbol" text NOT NULL,"rate" numeric(18, 6) NOT NULL DEFAULT '1',"active" boolean NOT NULL DEFAULT true);
CREATE TABLE "clients" ("id" serial PRIMARY KEY NOT NULL,"reference" text NOT NULL UNIQUE,"type" text NOT NULL DEFAULT 'particulier',"first_name" text NOT NULL,"last_name" text NOT NULL,"company_name" text,"phone" text,"email" text,"address" text,"city" text,"country" text,"nationality" text,"birth_date" date,"passport_number" text,"passport_expiry" date,"notes" text,"created_by" text,"created_at" timestamp NOT NULL DEFAULT now(),"updated_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "travelers" ("id" serial PRIMARY KEY NOT NULL,"client_id" integer NOT NULL,"first_name" text NOT NULL,"last_name" text NOT NULL,"relation" text NOT NULL DEFAULT 'titulaire',"birth_date" date,"gender" text,"nationality" text,"passport_number" text,"passport_expiry" date,"created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "dossiers" ("id" serial PRIMARY KEY NOT NULL,"reference" text NOT NULL UNIQUE,"client_id" integer NOT NULL,"agent_id" text,"title" text NOT NULL,"destination" text,"status" text NOT NULL DEFAULT 'en_attente',"priority" text NOT NULL DEFAULT 'normale',"departure_date" date,"return_date" date,"due_date" date,"notes" text,"created_by" text,"created_at" timestamp NOT NULL DEFAULT now(),"updated_at" timestamp NOT NULL DEFAULT now(),"closed_at" timestamp);
CREATE TABLE "dossier_travelers" ("dossier_id" integer NOT NULL,"traveler_id" integer NOT NULL,PRIMARY KEY ("dossier_id","traveler_id"));
CREATE TABLE "dossier_steps" ("id" serial PRIMARY KEY NOT NULL,"dossier_id" integer NOT NULL,"label" text NOT NULL,"note" text,"user_id" text,"user_name" text,"created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "suppliers" ("id" serial PRIMARY KEY NOT NULL,"name" text NOT NULL,"category" text NOT NULL DEFAULT 'autre',"contact_name" text,"phone" text,"email" text,"address" text,"notes" text,"active" boolean NOT NULL DEFAULT true,"created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "services" ("id" serial PRIMARY KEY NOT NULL,"dossier_id" integer NOT NULL,"type" text NOT NULL,"status" text NOT NULL,"supplier_id" integer,"description" text NOT NULL,"cost_price" numeric(14, 2) NOT NULL DEFAULT '0',"sale_price" numeric(14, 2) NOT NULL DEFAULT '0',"currency" text NOT NULL DEFAULT 'USD',"rate" numeric(18, 6) NOT NULL DEFAULT '1',"details" jsonb NOT NULL DEFAULT '{}'::jsonb,"created_at" timestamp NOT NULL DEFAULT now(),"updated_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "commercial_docs" ("id" serial PRIMARY KEY NOT NULL,"kind" text NOT NULL,"number" text NOT NULL UNIQUE,"dossier_id" integer NOT NULL,"client_id" integer NOT NULL,"status" text NOT NULL,"issue_date" date NOT NULL DEFAULT now(),"due_date" date,"currency" text NOT NULL DEFAULT 'USD',"rate" numeric(18, 6) NOT NULL DEFAULT '1',"subtotal" numeric(14, 2) NOT NULL DEFAULT '0',"discount" numeric(14, 2) NOT NULL DEFAULT '0',"total" numeric(14, 2) NOT NULL DEFAULT '0',"notes" text,"source_quote_id" integer,"created_by" text,"created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "doc_lines" ("id" serial PRIMARY KEY NOT NULL,"doc_id" integer NOT NULL,"service_id" integer,"description" text NOT NULL,"quantity" numeric(10, 2) NOT NULL DEFAULT '1',"unit_price" numeric(14, 2) NOT NULL DEFAULT '0',"total" numeric(14, 2) NOT NULL DEFAULT '0',"position" integer NOT NULL DEFAULT 0);
CREATE TABLE "payments" ("id" serial PRIMARY KEY NOT NULL,"receipt_number" text NOT NULL UNIQUE,"invoice_id" integer NOT NULL,"client_id" integer NOT NULL,"dossier_id" integer NOT NULL,"amount" numeric(14, 2) NOT NULL,"currency" text NOT NULL,"rate" numeric(18, 6) NOT NULL DEFAULT '1',"applied_amount" numeric(14, 2) NOT NULL,"method" text NOT NULL,"reference" text,"paid_at" date NOT NULL DEFAULT now(),"notes" text,"created_by" text,"created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "supplier_payments" ("id" serial PRIMARY KEY NOT NULL,"supplier_id" integer NOT NULL,"service_id" integer,"amount" numeric(14, 2) NOT NULL,"currency" text NOT NULL DEFAULT 'USD',"rate" numeric(18, 6) NOT NULL DEFAULT '1',"method" text NOT NULL,"reference" text,"paid_at" date NOT NULL DEFAULT now(),"notes" text,"created_by" text,"created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "expenses" ("id" serial PRIMARY KEY NOT NULL,"category" text NOT NULL,"label" text NOT NULL,"amount" numeric(14, 2) NOT NULL,"currency" text NOT NULL DEFAULT 'USD',"rate" numeric(18, 6) NOT NULL DEFAULT '1',"method" text NOT NULL,"paid_at" date NOT NULL DEFAULT now(),"notes" text,"created_by" text,"created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "cash_movements" ("id" serial PRIMARY KEY NOT NULL,"direction" text NOT NULL,"label" text NOT NULL,"amount" numeric(14, 2) NOT NULL,"currency" text NOT NULL DEFAULT 'USD',"rate" numeric(18, 6) NOT NULL DEFAULT '1',"occurred_at" date NOT NULL DEFAULT now(),"notes" text,"created_by" text,"created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "files" ("id" serial PRIMARY KEY NOT NULL,"client_id" integer,"dossier_id" integer,"category" text NOT NULL DEFAULT 'autre',"name" text NOT NULL,"pathname" text NOT NULL,"content_type" text,"size" integer,"confidential" boolean NOT NULL DEFAULT false,"uploaded_by" text,"uploaded_by_name" text,"created_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "audit_logs" ("id" serial PRIMARY KEY NOT NULL,"user_id" text,"user_name" text,"action" text NOT NULL,"entity" text NOT NULL,"entity_id" text,"details" text,"created_at" timestamp NOT NULL DEFAULT now());
